-- c016-v001: Y habiendo–pasado el– sábado * María * Magdalēnḗ y María la– de– Iakṓbou y Salṓmē compraron especias para–que habiendo–venido ungieran a–él
-- c016-v002: Y muy temprano el– primero de–los– sábados vienen a el– sepulcro habiendo–salido el– sol
-- c016-v003: Y decían entre sí–mismas quién rodará para–nosotras la– piedra de la– puerta del– sepulcro
-- c016-v004: Y habiendo–alzado–la–vista ven que ha–sido–rodada la– piedra era porque grande muy
-- c016-v005: Y habiendo–entrado en el– sepulcro vieron joven sentado en los– diestros vestido vestidura blanca y se–asombraron
-- c016-v006: * pero– dice a–ellas No os–asombréis a–Iēsoûn buscáis al– Nazarēnón al– crucificado ha–resucitado no está aquí mirad el– lugar donde pusieron a–él
-- c016-v007: Pero id decid a–los– discípulos de–él y a– Pétrōi que va–delante–de vosotros a la– Galilaían allí a–él veréis como dijo a–vosotros
-- c016-v008: Y habiendo–salido huyeron de el– sepulcro tenía porque a–ellas temblor y asombro y a–nadie nada dijeron temían porque
-- c016-v009: Habiendo–resucitado pero– temprano primero del–sábado apareció primero a–María la– Magdalēnêi de– quien había–echado–fuera siete demonios
-- c016-v010: Aquella habiendo–ido anunció a–los– con él habiendo–estado lamentando y llorando
-- c016-v011: Y–aquellos habiendo–oído que vive y fue–visto por ella no–creyeron
-- c016-v012: Después–de pero– estas–cosas a–dos de ellos caminando se–manifestó en otra forma yendo a campo
-- c016-v013: Y–aquellos habiendo–ido anunciaron a–los– demás ni–siquiera a–aquellos creyeron
-- c016-v014: Después pero– estando–recostados a–ellos los– once se–manifestó y reprochó la– incredulidad de–ellos y dureza–de–corazón porque a–los– que–habían–visto a–él resucitado de– muertos no creyeron
-- c016-v015: Y dijo a–ellos Habiendo–ido a el– mundo todo proclamad el– evangelio a–toda la– creación
-- c016-v016: El– que–creyere y fuere–bautizado será–salvo el– pero– que–no–creyere será–condenado
-- c016-v017: señales pero– a–los– que–creyeren estas seguirán en el– nombre de–mí demonios echarán–fuera en–lenguas hablarán nuevas
-- c016-v018: y en las– manos serpientes tomarán y–si mortal algo bebieren no de–ningún–modo a–ellos dañará sobre enfermos manos pondrán y bien tendrán
-- c016-v019: El– ciertamente pues Señor Iēsoûs después–de el– hablar a–ellos fue–llevado–arriba a el– cielo y se–sentó a diestra del– Theoû
-- c016-v020: Aquellos pero– habiendo–salido proclamaron en–todas–partes del– Señor cooperando y la– palabra confirmando por–medio–de las– que–acompañaban señales todo pero– lo– mandado a–los– alrededor–de el– Pétron brevemente anunciaron después–de pero– estas–cosas también él–mismo * Iēsoûs desde oriente y hasta occidente envió por–medio–de ellos el– sagrado e incorruptible mensaje de–la– eterna salvación amén

